// AgentServiceHandler is an implementation of the harness.agent.v1.AgentService service.
type AgentServiceHandler interface {
	Initialize(context.Context, *connect.Request[v1.InitializeRequest]) (*connect.Response[v1.InitializeResponse], error)
	CreateSession(context.Context, *connect.Request[v1.CreateSessionRequest]) (*connect.Response[v1.CreateSessionResponse], error)
	// Sessions on this machine (local transcripts and live sessions) with the per-user state stored on the harness
	// server (pinned, unread, archived, renamed title), plus the user's sessions of other machines listed from the
	// server (SessionInfo.remote, with their device and, when known, its relay presence). A session the server
	// lists that is also on this machine appears once, as local. Archived sessions are left out unless
	// include_archived.
	ListSessions(context.Context, *connect.Request[v1.ListSessionsRequest]) (*connect.Response[v1.ListSessionsResponse], error)
	// Changes the per-user state of a session: pin, unread, archive (which also stops it), or a rename. The state is
	// stored on the harness server (SyncService), for remote sessions too; without a server connection only a rename
	// can be applied (FAILED_PRECONDITION for the rest), and when the server is unreachable nothing is changed
	// (UNAVAILABLE).
	UpdateSession(context.Context, *connect.Request[v1.UpdateSessionRequest]) (*connect.Response[v1.UpdateSessionResponse], error)
	// Deletes a session for good: stops it if live, deletes its server copy and its local transcript files (a
	// remote session: its server copy only). When the server is unreachable nothing is deleted (UNAVAILABLE).
	DeleteSession(context.Context, *connect.Request[v1.DeleteSessionRequest]) (*connect.Response[v1.DeleteSessionResponse], error)
	// --- New-session pickers (folder, branch, worktree) ---
	// Folders recently used for sessions on this machine, most recent first.
	ListRecentFolders(context.Context, *connect.Request[v1.ListRecentFoldersRequest]) (*connect.Response[v1.ListRecentFoldersResponse], error)
	// Subdirectories of a folder, for an "Open folder…" browser. Hidden entries are left out unless asked.
	ListDirectory(context.Context, *connect.Request[v1.ListDirectoryRequest]) (*connect.Response[v1.ListDirectoryResponse], error)
	// Local branches of the repository containing `cwd` (empty outside a repository).
	ListBranches(context.Context, *connect.Request[v1.ListBranchesRequest]) (*connect.Response[v1.ListBranchesResponse], error)
	// Replays events after `after_seq`, then streams live events (history first, then live; no gaps, no duplicates).
	// With `control`, the stream also carries control messages (SubscribeResponse without an event): one before
	// the replay and one right after it (with the session as it is now), then a heartbeat every 15 seconds; a
	// frontend that hears nothing for much longer treats the stream as dead and subscribes again.
	// A remote session (SessionInfo.remote) is followed live through the relay when it is remote_controllable;
	// otherwise its durable transcript is read from the harness server and replayed, and the stream then ends.
	Subscribe(context.Context, *connect.Request[v1.SubscribeRequest], *connect.ServerStream[v1.SubscribeResponse]) error
	// Sent while a turn is running, the message is queued and injected after the current tool calls (QUEUE),
	// or the turn is interrupted / backgrounded so it is read right away (NOW).
	SendUserMessage(context.Context, *connect.Request[v1.SendUserMessageRequest]) (*connect.Response[v1.SendUserMessageResponse], error)
	// Takes back a message that is still queued (by its uuid); a QueueChanged event follows.
	// removed = false when it was already injected into the turn.
	RemoveQueuedMessage(context.Context, *connect.Request[v1.RemoveQueuedMessageRequest]) (*connect.Response[v1.RemoveQueuedMessageResponse], error)
	// Cancels in-flight tools and generation; already completed work is kept. With no turn running it reports
	// idle and publishes SessionUpdated, so a frontend that missed the end of a turn catches up.
	Interrupt(context.Context, *connect.Request[v1.InterruptRequest]) (*connect.Response[v1.InterruptResponse], error)
	RespondToPermission(context.Context, *connect.Request[v1.RespondToPermissionRequest]) (*connect.Response[v1.RespondToPermissionResponse], error)
	AnswerQuestion(context.Context, *connect.Request[v1.AnswerQuestionRequest]) (*connect.Response[v1.AnswerQuestionResponse], error)
	SetModel(context.Context, *connect.Request[v1.SetModelRequest]) (*connect.Response[v1.SetModelResponse], error)
	SetEffort(context.Context, *connect.Request[v1.SetEffortRequest]) (*connect.Response[v1.SetEffortResponse], error)
	SetPermissionMode(context.Context, *connect.Request[v1.SetPermissionModeRequest]) (*connect.Response[v1.SetPermissionModeResponse], error)
	// Switches the output style (built-in id, or a user/project style name); "default" clears it.
	SetOutputStyle(context.Context, *connect.Request[v1.SetOutputStyleRequest]) (*connect.Response[v1.SetOutputStyleResponse], error)
	// Built-in, user and project output styles available to this session.
	ListOutputStyles(context.Context, *connect.Request[v1.ListOutputStylesRequest]) (*connect.Response[v1.ListOutputStylesResponse], error)
	// Fuzzy file paths for @-mentions.
	SuggestFiles(context.Context, *connect.Request[v1.SuggestFilesRequest]) (*connect.Response[v1.SuggestFilesResponse], error)
	// Approves or rejects a plan proposed with ExitPlanMode (see PlanProposed).
	RespondToPlan(context.Context, *connect.Request[v1.RespondToPlanRequest]) (*connect.Response[v1.RespondToPlanResponse], error)
	// Checkpoints are taken before every turn that starts from a user prompt (file tools only).
	ListCheckpoints(context.Context, *connect.Request[v1.ListCheckpointsRequest]) (*connect.Response[v1.ListCheckpointsResponse], error)
	// Restores code and/or conversation to a checkpoint, or summarizes from / up to it.
	Rewind(context.Context, *connect.Request[v1.RewindRequest]) (*connect.Response[v1.RewindResponse], error)
	// Compacts the conversation now (same as /compact), with optional focus instructions.
	Compact(context.Context, *connect.Request[v1.CompactRequest]) (*connect.Response[v1.CompactResponse], error)
	// What fills the session's context window, by category (see ContextUsage). Computed on demand: frontends
	// ask when a context view opens and again after turns while it stays open. Local sessions only.
	GetContextUsage(context.Context, *connect.Request[v1.GetContextUsageRequest]) (*connect.Response[v1.GetContextUsageResponse], error)
	// Per-user preferences that the client honours for every session (stored in the user's synced settings
	// document). Without a server connection Get returns the defaults and Update fails with FAILED_PRECONDITION.
	GetUserPreferences(context.Context, *connect.Request[v1.GetUserPreferencesRequest]) (*connect.Response[v1.GetUserPreferencesResponse], error)
	UpdateUserPreferences(context.Context, *connect.Request[v1.UpdateUserPreferencesRequest]) (*connect.Response[v1.UpdateUserPreferencesResponse], error)
	// Background tasks: shell commands started with run_in_background or moved to the background.
	ListTasks(context.Context, *connect.Request[v1.ListTasksRequest]) (*connect.Response[v1.ListTasksResponse], error)
	StopTask(context.Context, *connect.Request[v1.StopTaskRequest]) (*connect.Response[v1.StopTaskResponse], error)
	// Ends the session process-side (kills background tasks, flushes the transcript).
	CloseSession(context.Context, *connect.Request[v1.CloseSessionRequest]) (*connect.Response[v1.CloseSessionResponse], error)
	// Workspace trust (~/.harness/trust.json): project hooks, .mcp.json servers and allow rules from
	// committed settings apply only in trusted folders. Frontends ask before the first session in a folder.
	GetWorkspaceTrust(context.Context, *connect.Request[v1.GetWorkspaceTrustRequest]) (*connect.Response[v1.GetWorkspaceTrustResponse], error)
	SetWorkspaceTrust(context.Context, *connect.Request[v1.SetWorkspaceTrustRequest]) (*connect.Response[v1.SetWorkspaceTrustResponse], error)
	// Terminals (terminal.proto): shells in a PTY, with I/O over a WebSocket authenticated by one-time tickets.
	// CreateTerminal starts one and returns a ticket; AttachTerminal returns a fresh ticket to reconnect.
	CreateTerminal(context.Context, *connect.Request[v1.CreateTerminalRequest]) (*connect.Response[v1.CreateTerminalResponse], error)
	AttachTerminal(context.Context, *connect.Request[v1.AttachTerminalRequest]) (*connect.Response[v1.AttachTerminalResponse], error)
	ListTerminals(context.Context, *connect.Request[v1.ListTerminalsRequest]) (*connect.Response[v1.ListTerminalsResponse], error)
	// Ends the shell (if still running) and forgets the terminal.
	KillTerminal(context.Context, *connect.Request[v1.KillTerminalRequest]) (*connect.Response[v1.KillTerminalResponse], error)
	ResizeTerminal(context.Context, *connect.Request[v1.ResizeTerminalRequest]) (*connect.Response[v1.ResizeTerminalResponse], error)
	// --- Environments (packages/client/server/environment.go) ---
	// An environment belongs to a primary folder (project) and is stored on this machine under HARNESS_HOME,
	// keyed by the folder's absolute path: a name, additional folders, new-session defaults (worktree, base
	// branch) and environment variables in .env syntax. Sessions started in the folder use it: the additional
	// folders become working directories and the variables are set for shell commands, background tasks and the
	// other processes tools spawn. The variables are encrypted at rest (see Environment.env).
	//
	// Returns the environment of a folder, or of a session's primary folder. A folder without one returns the
	// defaults (exists = false). A remote session's environment lives on its machine: read_only, nothing else set.
	GetEnvironment(context.Context, *connect.Request[v1.GetEnvironmentRequest]) (*connect.Response[v1.GetEnvironmentResponse], error)
	// Replaces the environment of a folder and applies it to the open sessions in that folder from their next tool
	// call: working directories and environment variables change live; worktree and base branch only affect new
	// sessions; MCP servers already started keep their environment. Invalid .env text fails with
	// INVALID_ARGUMENT and an EnvironmentErrors detail (line numbers). A remote session is refused
	// (FAILED_PRECONDITION).
	UpdateEnvironment(context.Context, *connect.Request[v1.UpdateEnvironmentRequest]) (*connect.Response[v1.UpdateEnvironmentResponse], error)
	// Git facts of a folder for its menu: repository root, current and default branch, and the remote as a
	// browsable URL ("Open repository on GitHub").
	GetFolderInfo(context.Context, *connect.Request[v1.GetFolderInfoRequest]) (*connect.Response[v1.GetFolderInfoResponse], error)
	// Moves an idle session to another primary folder. The conversation is kept (same session id, the transcript
	// moves to the new folder's project directory); the tools start over in the new folder: the live session is
	// closed (SessionEnded reason "folder_changed": background tasks stop, the shell cwd resets) and reopened
	// with the new folder's settings, permissions, instructions, MCP servers and environment. Subscribers
	// subscribe again (after_seq = 0). FAILED_PRECONDITION while a turn runs, for a session in a harness worktree
	// and for remote sessions.
	SetSessionFolder(context.Context, *connect.Request[v1.SetSessionFolderRequest]) (*connect.Response[v1.SetSessionFolderResponse], error)
	// Adds a working directory to an open session's environment (stored) and applies it to the open sessions
	// in that folder, this one included, from their next tool call. FAILED_PRECONDITION for remote sessions.
	AddSessionDirectory(context.Context, *connect.Request[v1.AddSessionDirectoryRequest]) (*connect.Response[v1.AddSessionDirectoryResponse], error)
	// --- Files (files.proto, packages/client/server/filebrowser.go) ---
	// The files pane: a session's working directories, their listings with git status and .gitignore marks, file
	// contents within limits, and the repository's changed paths. Paths must stay inside the working directories
	// (PERMISSION_DENIED otherwise); sessions of other machines are FAILED_PRECONDITION.
	ListFileRoots(context.Context, *connect.Request[v1.ListFileRootsRequest]) (*connect.Response[v1.ListFileRootsResponse], error)
	ListFiles(context.Context, *connect.Request[v1.ListFilesRequest]) (*connect.Response[v1.ListFilesResponse], error)
	ReadFile(context.Context, *connect.Request[v1.ReadFileRequest]) (*connect.Response[v1.ReadFileResponse], error)
	GetGitStatus(context.Context, *connect.Request[v1.GetGitStatusRequest]) (*connect.Response[v1.GetGitStatusResponse], error)
	// --- User shell commands (shell.proto) ---
	// Runs a command from the composer's shell mode in the session's shell, without the model and without a
	// permission prompt, at once (also while a turn runs). Returns when it started; UserShellStarted / Output /
	// Finished events follow, and the result reaches the model on its next request. FAILED_PRECONDITION for
	// remote sessions.
	RunShellCommand(context.Context, *connect.Request[v1.RunShellCommandRequest]) (*connect.Response[v1.RunShellCommandResponse], error)
	// Kills a running user shell command (UserShellFinished reason STOPPED). NOT_FOUND when it is not running.
	StopShellCommand(context.Context, *connect.Request[v1.StopShellCommandRequest]) (*connect.Response[v1.StopShellCommandResponse], error)
	// Side chats (sidechat.proto): read-only conversations next to a session that see its conversation but never
	// change it (no tools). Stored next to the session's transcript. Local open sessions only.
	ListSideChats(context.Context, *connect.Request[v1.ListSideChatsRequest]) (*connect.Response[v1.ListSideChatsResponse], error)
	CreateSideChat(context.Context, *connect.Request[v1.CreateSideChatRequest]) (*connect.Response[v1.CreateSideChatResponse], error)
	// The side chat with its messages.
	GetSideChat(context.Context, *connect.Request[v1.GetSideChatRequest]) (*connect.Response[v1.GetSideChatResponse], error)
	// Renames it or changes its model / effort (remembered for this side chat only).
	UpdateSideChat(context.Context, *connect.Request[v1.UpdateSideChatRequest]) (*connect.Response[v1.UpdateSideChatResponse], error)
	// Stops a running answer and deletes the side chat.
	DeleteSideChat(context.Context, *connect.Request[v1.DeleteSideChatRequest]) (*connect.Response[v1.DeleteSideChatResponse], error)
	// Asks a question: streams the stored question, the answer's text deltas and the stored answer with usage.
	// Cancelling the stream stops the answer like StopSideChat.
	AskSideChat(context.Context, *connect.Request[v1.AskSideChatRequest], *connect.ServerStream[v1.AskSideChatResponse]) error
	// Stops the running answer of a side chat; the text so far is kept (stopped = true).
	StopSideChat(context.Context, *connect.Request[v1.StopSideChatRequest]) (*connect.Response[v1.StopSideChatResponse], error)
	// --- Speech (speech.proto, packages/client/server/speech.go) ---
	// Speech providers for dictation (STT) and "Read aloud" (TTS): the local engines of this machine and the
	// server's global providers, with models, voices and availability.
	ListSpeechProviders(context.Context, *connect.Request[v1.ListSpeechProvidersRequest]) (*connect.Response[v1.ListSpeechProvidersResponse], error)
	// Voices of a TTS provider (the provider's API for global providers that list them; installed and
	// downloadable voices for Piper; `say -v ?` for macOS).
	ListSpeechVoices(context.Context, *connect.Request[v1.ListSpeechVoicesRequest]) (*connect.Response[v1.ListSpeechVoicesResponse], error)
	// The user's speech choices in two parts: the synced choice of a global provider (the user's synced settings
	// document, key "speech") and this device's choice of a local engine (HARNESS_HOME/speech/settings.json, never
	// synced), which overrides the synced one on this device.
	GetSpeechSettings(context.Context, *connect.Request[v1.GetSpeechSettingsRequest]) (*connect.Response[v1.GetSpeechSettingsResponse], error)
	UpdateSpeechSettings(context.Context, *connect.Request[v1.UpdateSpeechSettingsRequest]) (*connect.Response[v1.UpdateSpeechSettingsResponse], error)
	// Speech to text with the chosen (or given) provider: a local engine on this machine or the server.
	TranscribeAudio(context.Context, *connect.Request[v1.TranscribeAudioRequest]) (*connect.Response[v1.TranscribeAudioResponse], error)
	// Text to speech with the chosen (or given) provider; Markdown is turned into speakable text first. The audio
	// streams back in pieces so playback can start early.
	SynthesizeSpeech(context.Context, *connect.Request[v1.SynthesizeSpeechRequest], *connect.ServerStream[v1.SynthesizeSpeechResponse]) error
	// Model files of the local engines: installed state, downloads with progress, deletion.
	ListLocalSpeechModels(context.Context, *connect.Request[v1.ListLocalSpeechModelsRequest]) (*connect.Response[v1.ListLocalSpeechModelsResponse], error)
	DownloadSpeechModel(context.Context, *connect.Request[v1.DownloadSpeechModelRequest], *connect.ServerStream[v1.DownloadSpeechModelResponse]) error
	DeleteSpeechModel(context.Context, *connect.Request[v1.DeleteSpeechModelRequest]) (*connect.Response[v1.DeleteSpeechModelResponse], error)
	// Detected and configured local providers with their models (cached probes; refresh = probe now).
	ListLocalProviders(context.Context, *connect.Request[v1.ListLocalProvidersRequest]) (*connect.Response[v1.ListLocalProvidersResponse], error)
	// Adds an endpoint (e.g. a custom OpenAI-compatible server); it is probed right away.
	AddLocalProvider(context.Context, *connect.Request[v1.AddLocalProviderRequest]) (*connect.Response[v1.AddLocalProviderResponse], error)
	// Renames, moves, re-keys, enables or disables a provider.
	UpdateLocalProvider(context.Context, *connect.Request[v1.UpdateLocalProviderRequest]) (*connect.Response[v1.UpdateLocalProviderResponse], error)
	RemoveLocalProvider(context.Context, *connect.Request[v1.RemoveLocalProviderRequest]) (*connect.Response[v1.RemoveLocalProviderResponse], error)
	// Probes the providers again (all enabled ones, or one).
	RefreshLocalProviders(context.Context, *connect.Request[v1.RefreshLocalProvidersRequest]) (*connect.Response[v1.RefreshLocalProvidersResponse], error)
	// Downloads a model into an Ollama server, streaming its progress; cancelling the stream stops the pull.
	PullOllamaModel(context.Context, *connect.Request[v1.PullOllamaModelRequest], *connect.ServerStream[v1.PullOllamaModelResponse]) error
	DeleteOllamaModel(context.Context, *connect.Request[v1.DeleteOllamaModelRequest]) (*connect.Response[v1.DeleteOllamaModelResponse], error)
}

